import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"VPS Elastic IP User Guide","description":"","frontmatter":{"title":"VPS Elastic IP User Guide"},"headers":[],"relativePath":"operations-knowledge-base/vps/vps-elastic-ip-user-guide.md","filePath":"operations-knowledge-base/vps/vps-elastic-ip-user-guide.md","lastUpdated":1794292919000}'),s={name:"operations-knowledge-base/vps/vps-elastic-ip-user-guide.md"};function l(r,e,o,c,d,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document introduces the features, usage scenarios, and management procedures for VPS Elastic IPs (EIP). It helps users understand how to bind, unbind, and manage Elastic IPs through the Raksmart control panel.</p><p><strong>Applicable Products:</strong></p><ul><li>VPS (Virtual Private Server)</li></ul><hr><h2 id="_1-what-is-an-elastic-ip-eip" tabindex="-1">1. What is an Elastic IP (EIP)? <a class="header-anchor" href="#_1-what-is-an-elastic-ip-eip" aria-label="Permalink to &quot;1. What is an Elastic IP (EIP)?&quot;">​</a></h2><p>An Elastic IP (EIP) is a public IP address that can be managed independently and bound to or unbound from a VPS instance as needed.</p><p>Unlike the default public IP assigned to a VPS, an Elastic IP can be managed separately, making it more flexible for server migration and network management.</p><p><strong>Common Use Cases:</strong></p><ul><li>Assign an additional public IP to a VPS.</li><li>Rebind an existing public IP to another VPS.</li><li>Flexibly manage public IP resources for different business scenarios.</li></ul><hr><h2 id="_2-accessing-the-elastic-ip-management-page" tabindex="-1">2. Accessing the Elastic IP Management Page <a class="header-anchor" href="#_2-accessing-the-elastic-ip-management-page" aria-label="Permalink to &quot;2. Accessing the Elastic IP Management Page&quot;">​</a></h2><ol><li>Log in to the Raksmart Client Area.</li><li>Navigate to:</li></ol><p><strong>Products &amp; Services → VPS → Elastic IP</strong></p><p>On the Elastic IP management page, you can view all Elastic IPs under your account, including:</p><ul><li>IP Address</li><li>Region</li><li>Network Route</li><li>Status (Bound / Available)</li><li>Associated VPS Instance (if applicable)</li></ul><hr><h2 id="_3-binding-an-elastic-ip" tabindex="-1">3. Binding an Elastic IP <a class="header-anchor" href="#_3-binding-an-elastic-ip" aria-label="Permalink to &quot;3. Binding an Elastic IP&quot;">​</a></h2><p>When an Elastic IP is in the <strong>Available</strong> state, it can be bound to a VPS.</p><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Log in to the Raksmart Client Area.</li><li>Go to <strong>Products &amp; Services → VPS → Elastic IP</strong>.</li><li>Select the Elastic IP you want to use.</li><li>Click <strong>Allocation</strong>.</li><li>Select the target VPS instance.</li><li>Confirm the operation.</li></ol><p>After the binding is completed, the VPS will automatically reboot to apply the new network configuration.</p><blockquote><p><strong>Note:</strong></p><p>Binding an Elastic IP will automatically restart the VPS. Please ensure that your business can tolerate the temporary service interruption before proceeding.</p></blockquote><hr><h2 id="_4-unbinding-an-elastic-ip" tabindex="-1">4. Unbinding an Elastic IP <a class="header-anchor" href="#_4-unbinding-an-elastic-ip" aria-label="Permalink to &quot;4. Unbinding an Elastic IP&quot;">​</a></h2><p>If you no longer need an Elastic IP to be associated with the current VPS, you can unbind it.</p><p>There are two ways to unbind an Elastic IP.</p><h3 id="method-1-unbind-from-the-elastic-ip-page" tabindex="-1">Method 1: Unbind from the Elastic IP Page <a class="header-anchor" href="#method-1-unbind-from-the-elastic-ip-page" aria-label="Permalink to &quot;Method 1: Unbind from the Elastic IP Page&quot;">​</a></h3><ol><li>Go to <strong>Products &amp; Services → VPS → Elastic IP</strong>.</li><li>Locate the bound Elastic IP.</li><li>Click <strong>Idle</strong>.</li><li>Confirm the operation.</li></ol><p>Once unbound, the Elastic IP will return to the <strong>Available</strong> state and can be bound to another eligible VPS.</p><blockquote><p><strong>Note:</strong></p><p>Unbinding an Elastic IP will also automatically restart the VPS.</p></blockquote><hr><h2 id="_5-binding-requirements" tabindex="-1">5. Binding Requirements <a class="header-anchor" href="#_5-binding-requirements" aria-label="Permalink to &quot;5. Binding Requirements&quot;">​</a></h2><p>An Elastic IP cannot be bound to any VPS arbitrarily. The following requirements must be met:</p><ul><li>The Elastic IP and the VPS <strong>must be located in the same region</strong>.</li><li>The Elastic IP and the VPS <strong>must use the same network route</strong>.</li></ul><p>For example:</p><ul><li>A Los Angeles International BGP Elastic IP can only be bound to a Los Angeles International BGP VPS.</li><li>A Japan Mainland Optimized Elastic IP cannot be bound to a Japan International BGP VPS.</li></ul><p>If the VPS does not meet these requirements, it <strong>will not appear in the instance selection list</strong>, and the binding cannot be completed.</p><hr><h2 id="_6-recommended-usage" tabindex="-1">6. Recommended Usage <a class="header-anchor" href="#_6-recommended-usage" aria-label="Permalink to &quot;6. Recommended Usage&quot;">​</a></h2><p>Elastic IPs are recommended for the following scenarios:</p><ul><li>Flexible public IP management.</li><li>Migrating services to another VPS.</li><li>Retaining the same public IP after replacing a VPS.</li><li>Managing multiple public IP resources.</li></ul><p>If your VPS does not require public IP reassignment, you may continue using the default public IP assigned to the instance.</p><hr><h2 id="_7-frequently-asked-questions" tabindex="-1">7. Frequently Asked Questions <a class="header-anchor" href="#_7-frequently-asked-questions" aria-label="Permalink to &quot;7. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-why-can-t-i-find-my-vps-when-binding-an-elastic-ip" tabindex="-1">Q1: Why can&#39;t I find my VPS when binding an Elastic IP? <a class="header-anchor" href="#q1-why-can-t-i-find-my-vps-when-binding-an-elastic-ip" aria-label="Permalink to &quot;Q1: Why can&#39;t I find my VPS when binding an Elastic IP?&quot;">​</a></h3><p>This usually occurs because the Elastic IP and the VPS are not in the same <strong>region</strong> or do not use the same <strong>network route</strong>.</p><p>Please verify:</p><ul><li>The region matches.</li><li>The network route matches.</li></ul><p>Only VPS instances that satisfy both requirements will appear in the binding list.</p><hr><h3 id="q2-will-binding-an-elastic-ip-affect-my-server" tabindex="-1">Q2: Will binding an Elastic IP affect my server? <a class="header-anchor" href="#q2-will-binding-an-elastic-ip-affect-my-server" aria-label="Permalink to &quot;Q2: Will binding an Elastic IP affect my server?&quot;">​</a></h3><p>Yes.</p><p>The VPS will automatically reboot after the Elastic IP is bound to apply the new network configuration.</p><p>It is recommended to perform this operation during maintenance windows or periods of low business traffic.</p><hr><h3 id="q3-will-unbinding-an-elastic-ip-restart-my-vps" tabindex="-1">Q3: Will unbinding an Elastic IP restart my VPS? <a class="header-anchor" href="#q3-will-unbinding-an-elastic-ip-restart-my-vps" aria-label="Permalink to &quot;Q3: Will unbinding an Elastic IP restart my VPS?&quot;">​</a></h3><p>Yes.</p><p>The VPS will automatically reboot after the Elastic IP is unbound.</p><hr><h3 id="q4-will-the-elastic-ip-be-released-after-it-is-unbound" tabindex="-1">Q4: Will the Elastic IP be released after it is unbound? <a class="header-anchor" href="#q4-will-the-elastic-ip-be-released-after-it-is-unbound" aria-label="Permalink to &quot;Q4: Will the Elastic IP be released after it is unbound?&quot;">​</a></h3><p>No.</p><p>After unbinding, the Elastic IP remains under your account and changes to the <strong>Available</strong> state. It can be bound again to another eligible VPS.</p><hr><h3 id="q5-why-can-t-i-access-my-server-after-successfully-binding-an-elastic-ip" tabindex="-1">Q5: Why can&#39;t I access my server after successfully binding an Elastic IP? <a class="header-anchor" href="#q5-why-can-t-i-access-my-server-after-successfully-binding-an-elastic-ip" aria-label="Permalink to &quot;Q5: Why can&#39;t I access my server after successfully binding an Elastic IP?&quot;">​</a></h3><p>Please check the following:</p><ul><li>The VPS has completed the automatic reboot.</li><li>The security group or system firewall allows the required ports.</li><li>SSH (Linux) or RDP (Windows) services are running properly.</li><li>DNS records have been updated if you are accessing the server via a domain name.</li></ul><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ The Elastic IP and VPS <strong>must belong to the same region and use the same network route</strong>; otherwise, the binding operation is not supported.</p><p>⚠️ If the target VPS does not appear during the binding process, please verify that both the region and network route match.</p><p>⚠️ Both <strong>binding and unbinding</strong> an Elastic IP will automatically restart the VPS. Please plan accordingly to avoid service interruptions.</p><p>⚠️ Unbinding an Elastic IP does <strong>not</strong> release it. The Elastic IP remains in your account and can be bound again to another eligible VPS.</p>',73)])])}const g=a(s,[["render",l]]);export{p as __pageData,g as default};
